{
  "id": "V056",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "견적 작성 업무를 지원하려는 목적이 유지됩니다."
    },
    {
      "field": "action",
      "score": 1,
      "reason": "초안 반영과 검토는 언급되지만, 초안을 생성하는 행동은 명시되지 않습니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "견적서 초안, 가격·납기, 최종 견적 및 계약이 언급됩니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "고객이 보낸 부품 사양과 수량이 보존됩니다."
    },
    {
      "field": "output",
      "score": 1,
      "reason": "견적서 초안은 언급되나, 담당자가 가격과 납기를 검토하도록 초안을 만든다는 결과가 명시되지 않습니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "최종 견적 전송과 계약 승인 권한을 사람에게 둔다는 제약이 보존됩니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "지원되지 않는 기능의 추가가 없습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "담당자의 검토와 사람의 최종 권한이 구분되어 있습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "견적서 초안을 만들어 담당자가 가격과 납기를 검토하도록 하고 싶습니다.",
      "view_quote": "",
      "reason": "세 뷰 모두 초안 생성이 필요하다는 요청을 명시하지 않습니다."
    }
  ],
  "permission_interpretation": "최종 견적 전송과 계약 승인은 사람의 권한으로 남깁니다. 사람에게 항상 두 행동을 모두 수행한다는 뜻은 아닙니다."
}
